function lText(selector,value){const node=document.querySelector(selector);if(node)node.textContent=value;}
function lHero(values){lText('.page-hero .eyebrow',values[0]);lText('.page-hero h1',values[1]);lText('.page-hero p:not(.eyebrow)',values[2]);}
function currentGuidePage(){const name=location.pathname.split('/').pop();return !name||name==='index'?'index.html':name.endsWith('.html')?name:`${name}.html`;}
function renderLocale(code){const d=localeData[code]||localeData.en;const page=currentGuidePage();document.documentElement.lang=code;document.querySelectorAll('.database-search input:not([type="hidden"])').forEach(x=>x.placeholder=d.placeholder);document.querySelectorAll('.database-search button').forEach(x=>x.textContent=d.search);document.querySelectorAll('footer p').forEach(x=>x.textContent=d.footer);
const urls=['index.html','categories.html','product-details.html','pikobuy-order-research.html'];const nav=document.querySelector('nav');if(nav)nav.innerHTML=localeNav[code].map((x,i)=>`<a href="${urls[i]}?lang=${code}">${x}</a>`).join('')+`<a href="faq.html?lang=${code}">${d.faq}</a><a href="research-paths.html?lang=${code}">${d.research}</a>`;
if(page==='categories.html'){lHero(d.categories);lText('.page-content h2',d.categories[3]);document.querySelectorAll('.category-grid strong').forEach((x,i)=>x.textContent=d.cats[i]);}
if(page==='product-details.html'){lHero(d.details);const selected=new URLSearchParams(location.search).get('category');if(selected){const sourceCategories=['Shoes','Hoodies / Sweaters','T-Shirts','Jackets','Pants / Shorts','Headwear','Sets','Underwear / Underpants','Jersey','Accessories'];const categoryIndex=sourceCategories.indexOf(selected);const translatedCategory=categoryIndex>=0?d.cats[categoryIndex]:selected;const heading=document.querySelector('.page-hero h1');if(heading)heading.textContent=`${translatedCategory} — ${d.details[1]}`;}}
if(page==='faq.html'){lHero(d.faqHero);}
if(page==='research-paths.html'){lHero(d.researchHero);}
if(page==='seo-articles.html'){lHero(d.article.slice(0,3));}
if(page==='pikobuy-order-research.html'){const a=d.article;lText('.article-compact-hero .eyebrow',a[0]);lText('.article-compact-hero h2',a[1]);lText('.article-compact-hero p:not(.eyebrow)',a[2]);lText('article>.eyebrow',a[3]);lText('article h1',a[4]);lText('article .lead',a[5]);}
}
const rememberedLocale=()=>{try{return localStorage.getItem('piko-guide-language');}catch{return null;}};
const requestedLocale=()=>new URLSearchParams(location.search).get('lang')||rememberedLocale()||'en';
const storeLocale=code=>{try{localStorage.setItem('piko-guide-language',code);}catch{}};
function applyGuideLocale(code,updateUrl=true){const selected=localeData[code]?code:'en';storeLocale(selected);if(updateUrl){const url=new URL(location.href);url.searchParams.set('lang',selected);history.replaceState(null,'',url.pathname+url.search+url.hash);}renderLocale(selected);}
window.__applyGuideLocale=applyGuideLocale;
function bindGuideLocale(){if(window.__guideLocaleBound)return;const select=document.querySelector('.lang-wrap select');if(!select)return;window.__guideLocaleBound=true;select.value=localeData[requestedLocale()]?requestedLocale():'en';applyGuideLocale(select.value,false);document.addEventListener('change',event=>{if(event.target!==select)return;event.stopImmediatePropagation();applyGuideLocale(select.value);},true);}

